function timeline(rows){return rows.map(r=>'<article><time>'+r[0]+'</time><div><h3>'+r[1]+'</h3><p>'+r[2]+'</p></div></article>').join('')}
const cv='<section id="cv" class="cv section"><div class="section-heading"><div><span class="eyebrow">03 / ВИСТАВКИ ТА CV</span><h2>ТВОРЧИЙ<br>ШЛЯХ.</h2></div><a class="outline-link" href="assets/documents/Krystyna-Mishchenko-CV-UK.docx?v=20261023-editorial3" download>Завантажити CV · DOCX ↗</a></div><div class="cv-layout"><h3>ОСВІТА</h3><div class="timeline">'+timeline([['2020–2022','Магістр · Художня кераміка','Київська державна академія декоративно-прикладного мистецтва і дизайну імені Михайла Бойчука'],['2016–2020','Бакалавр · Художня кераміка','Київська державна академія декоративно-прикладного мистецтва і дизайну імені Михайла Бойчука'],['2012–2016','Художник-виконавець, викладач','Харківське художнє училище']])+'</div></div><div class="cv-layout"><h3>ВІДЗНАКИ</h3><div class="timeline">'+timeline([['2022','ZPAP · Варшава','Вступ до Спілки польських художників і дизайнерів у серпні 2022 року']])+'</div></div></section>';
